def assign_existing_qr_tokens(apps, schema_editor):
    Product = apps.get_model("inventory", "Product")
    for product in (
        Product.objects.using(schema_editor.connection.alias)
        .filter(qr_token__isnull=True)
        .iterator(chunk_size=1000)
    ):
        Product.objects.using(schema_editor.connection.alias).filter(
            pk=product.pk
        ).update(qr_token=uuid.uuid4())


